(() => {
  const unpack = async (value) => {
    const bytes = Uint8Array.from(atob(value), (char) => char.charCodeAt(0));
    const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
    return new Response(stream).text();
  };
  Promise.all([unpack(""), unpack("")])
    .then(([dataCode, verifiedCode]) => {
      Function(dataCode)();
      Function(verifiedCode)();
      const app = document.createElement("script");
      app.src = "app.js?v=19";
      document.body.appendChild(app);
    })
    .catch(() => {
      const target = document.querySelector("#price-rows");
      if (target) target.innerHTML = '<div class="empty-state"><h3>가격 데이터를 불러오지 못했습니다</h3><p>새로고침 후 다시 확인해 주세요.</p></div>';
    });
})();
